package br.com.sistemacardapio.pedido;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/public/clientes")public class ClientePublicController{private final ClientePublicService s;public ClientePublicController(ClientePublicService s){this.s=s;}@PostMapping("/cadastro")@ResponseStatus(HttpStatus.CREATED)public void cadastrar(@RequestBody ClientePublicService.Cadastro r){s.cadastrar(r);}@PostMapping("/historico")public List<ClientePublicService.PedidoCliente>historico(@RequestBody ClientePublicService.Login r){return s.historico(r);}}
